// Ida: prog 0→1 com E 0→π (períelio 1 AU na Terra → apélio 1.524 AU em Marte)
// Regresso: prog 0→1 com E π→0 (apélio 1.524 AU em Marte → períelio 1 AU na Terra)
function shipTransfer(prog, depDeg, isOutbound) {
  const E = isOutbound ? keplerE(Math.PI * prog, eT) : Math.PI - keplerE(Math.PI * prog, eT);
  const nu = 2 * Math.atan2(Math.sqrt(1 + eT) * Math.sin(E / 2),
                           Math.sqrt(1 - eT) * Math.cos(E / 2));
  const r  = aT * (1 - eT * Math.cos(E));
  const th = depDeg * RAD + nu;
  return { x: r * Math.cos(th), y: r * Math.sin(th) };
}

