    const q = auToPx(bodyPos(b, day));
    ctx.shadowColor = b.color; ctx.shadowBlur = 8;
    ctx.fillStyle = b.color;
    ctx.beginPath(); ctx.arc(q.x, q.y, b.size, 0, Math.PI * 2); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fillStyle = "rgba(230,240,255,0.85)";
    ctx.fillText(b.name, q.x + b.size + 5, q.y - 5);
  }

  // nave (segmentos percorridos, mais intensos)
  const d = ((day % TOTAL_DAYS) + TOTAL_DAYS) % TOTAL_DAYS;
  ctx.lineWidth = 2;
  if (d < OUT_DAYS) {
    const n = Math.max(2, Math.ceil(120 * d / OUT_DAYS));
    ctx.strokeStyle = "rgba(130,235,255,0.95)";
    ctx.beginPath();
    for (let i = 0; i <= n; i++) { const q = auToPx(shipTransfer(i / n, EARTH.a0, true)); i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y); }
    ctx.stroke();
  } else if (d < OUT_DAYS + STAY_DAYS) {
    ctx.strokeStyle = "rgba(130,235,255,0.95)";
    ctx.beginPath(); PATH_OUT.forEach((p, i) => { const q = auToPx(p); i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y); });
    const s = (d - OUT_DAYS) / STAY_DAYS;
    const n = Math.max(1, Math.ceil(80 * s));
    for (let i = 0; i <= n; i++) { const q = auToPx(PATH_STAY[Math.round(i * 80 / n)]); i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y); }
    ctx.stroke();
  } else if (d < TOTAL_DAYS) {
    ctx.strokeStyle = "rgba(130,235,255,0.95)";
    ctx.beginPath(); PATH_OUT.forEach((p, i) => { const q = auToPx(p); i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y); });
    ctx.beginPath(); PATH_STAY.forEach((p, i) => { if (i) ctx.lineTo(auToPx(p).x, auToPx(p).y); });
    const s = (d - OUT_DAYS - STAY_DAYS) / RET_DAYS;
    const n = Math.max(2, Math.ceil(120 * s));
    ctx.beginPath();
    for (let i = 0; i <= n; i++) { const q = auToPx(shipTransfer(i / n, MARS_DEP_ANGLE, false)); i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y); }
    ctx.stroke();
  }

  const sp = auToPx(shipAt(d));
  ctx.shadowColor = "#9adfff"; ctx.shadowBlur = 14;
  ctx.fillStyle = "#f4f9ff";
  ctx.beginPath(); ctx.arc(sp.x, sp.y, 4.5, 0, Math.PI * 2); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = "#d9f2ff";
  ctx.fillText("nave", sp.x + 8, sp.y + 12);
}


